const visual = {
  prepare: function (input) {
    return [
      { kind: 'text', payload: '植物细胞结构示意' },
      { kind: 'text', payload: '细胞壁' },
      { kind: 'text', payload: '液泡' },
      { kind: 'text', payload: '细胞核' }
    ];
  },
  render: function (input, metrics) {
    var W = (input && input.viewport && input.viewport.widthDu) || 600;
    var H = (input && input.viewport && input.viewport.heightDu) || 420;
    var m = metrics || [];

    function textWidth(index, text, fs) {
      var e = m[index];
      if (e && typeof e.width === 'number' && e.width > 0) return e.width;
      var sum = 0;
      for (var i = 0; i < text.length; i++) {
        sum += (text.charCodeAt(i) > 255 ? 1 : 0.55) * fs;
      }
      return sum;
    }

    function roundRectPoints(x, y, w, h, rad) {
      var r = Math.max(0, Math.min(rad, w / 2, h / 2));
      var pts = [];
      var seg = 8;
      function arc(cx, cy, a0, a1) {
        for (var i = 0; i <= seg; i++) {
          var a = a0 + (a1 - a0) * i / seg;
          pts.push([cx + Math.cos(a) * r, cy + Math.sin(a) * r]);
        }
      }
      arc(x + w - r, y + r, -Math.PI / 2, 0);
      arc(x + w - r, y + h - r, 0, Math.PI / 2);
      arc(x + r, y + h - r, Math.PI / 2, Math.PI);
      arc(x + r, y + r, Math.PI, Math.PI * 1.5);
      return pts;
    }

    function closed(pts) {
      var out = pts.slice();
      if (out.length) out.push([out[0][0], out[0][1]]);
      return visualSdk.polyline(out);
    }

    function ellipsePoints(cx, cy, rx, ry, n) {
      var pts = [];
      for (var i = 0; i < n; i++) {
        var a = Math.PI * 2 * i / n;
        pts.push([cx + Math.cos(a) * rx, cy + Math.sin(a) * ry]);
      }
      return pts;
    }

    var fs = Math.max(12, Math.min(20, H * 0.05));

    var cellX = W * 0.05;
    var cellY = H * 0.11;
    var cellW = W * 0.58;
    var cellH = H * 0.70;
    var cellRight = cellX + cellW;
    var t = Math.max(3, W * 0.016);
    var rOuter = Math.min(cellW, cellH) * 0.18;

    var wallPts = roundRectPoints(cellX, cellY, cellW, cellH, rOuter);
    var cytoPts = roundRectPoints(cellX + t, cellY + t, cellW - 2 * t, cellH - 2 * t, Math.max(2, rOuter - t));

    var vcx = cellX + cellW * 0.58;
    var vcy = cellY + cellH * 0.36;
    var vrx = cellW * 0.28;
    var vry = cellH * 0.30;

    var nr = Math.min(W * 0.075, H * 0.105);
    var ncx = cellX + cellW * 0.22;
    var ncy = cellY + cellH * 0.78;

    var wallLabelY = cellY + cellH * 0.26;
    var vacLabelY = H * 0.44;
    var nucLabelY = H * 0.93;

    var labelBaseX = W * 0.71;
    var wallW = textWidth(1, '细胞壁', fs);
    var vacW = textWidth(2, '液泡', fs);
    var wallX = Math.max(cellRight + W * 0.02, Math.min(labelBaseX, W - 10 - wallW));
    var vacX = Math.max(cellRight + W * 0.02, Math.min(labelBaseX, W - 10 - vacW));

    var wallEndX = Math.max(cellRight + 6, wallX - 12);
    var vacEndX = Math.max(cellRight + 6, vacX - 12);

    var leadWall = visualSdk.polyline([[cellRight, wallLabelY], [wallEndX, wallLabelY]]);
    var leadVac = visualSdk.polyline([[vcx + vrx, vcy], [cellRight * 0.976, vacLabelY], [vacEndX, vacLabelY]]);
    var leadNuc = visualSdk.polyline([[ncx, ncy + nr], [ncx, nucLabelY - fs * 1.05]]);

    var dotWall = visualSdk.circle(cellRight, wallLabelY, 2.4);
    var dotVac = visualSdk.circle(vcx + vrx, vcy, 2.4);
    var dotNuc = visualSdk.circle(ncx, ncy + nr, 2.4);

    var paths = [
      { id: 'wall', commands: closed(wallPts) },
      { id: 'cyto', commands: closed(cytoPts) },
      { id: 'vacuole', commands: closed(ellipsePoints(vcx, vcy, vrx, vry, 72)) },
      { id: 'nucleus', commands: visualSdk.circle(ncx, ncy, nr) },
      { id: 'nucleolus', commands: visualSdk.circle(ncx - nr * 0.22, ncy - nr * 0.18, nr * 0.38) },
      { id: 'lead-wall', commands: leadWall },
      { id: 'lead-vac', commands: leadVac },
      { id: 'lead-nuc', commands: leadNuc },
      { id: 'dot-wall', commands: dotWall },
      { id: 'dot-vac', commands: dotVac },
      { id: 'dot-nuc', commands: dotNuc }
    ];

    var root = {
      type: 'group',
      children: [
        { type: 'path', pathId: 'wall', fill: '#a9c68f', stroke: '#4f6f3c' },
        { type: 'path', pathId: 'cyto', fill: '#f3f9ea', stroke: '#4f6f3c' },
        { type: 'path', pathId: 'vacuole', fill: '#cfe6e9', stroke: '#5f8f96' },
        { type: 'path', pathId: 'nucleus', fill: '#e3d7ef', stroke: '#7a5f9c' },
        { type: 'path', pathId: 'nucleolus', fill: '#b89dd3', stroke: '#7a5f9c' },
        { type: 'path', pathId: 'lead-wall', stroke: '#3f5a52' },
        { type: 'path', pathId: 'lead-vac', stroke: '#3f5a52' },
        { type: 'path', pathId: 'lead-nuc', stroke: '#3f5a52' },
        { type: 'path', pathId: 'dot-wall', fill: '#3f5a52', stroke: '#3f5a52' },
        { type: 'path', pathId: 'dot-vac', fill: '#3f5a52', stroke: '#3f5a52' },
        { type: 'path', pathId: 'dot-nuc', fill: '#3f5a52', stroke: '#3f5a52' },
        { type: 'label', text: '植物细胞结构示意', x: W * 0.30, y: H * 0.065, fontSize: fs * 0.85, fill: '#22323a' },
        { type: 'label', text: '细胞壁', x: wallX, y: wallLabelY + fs * 0.35, fontSize: fs, fill: '#22323a' },
        { type: 'label', text: '液泡', x: vacX, y: vacLabelY + fs * 0.35, fontSize: fs, fill: '#22323a' },
        { type: 'label', text: '细胞核', x: ncx, y: nucLabelY, fontSize: fs, fill: '#22323a' }
      ]
    };

    return {
      schemaVersion: 1,
      sceneId: 'plant-cell-schematic',
      revision: input.revision,
      viewBox: { x: 0, y: 0, width: W, height: H },
      paths: paths,
      root: root
    };
  }
};
